const w = Number(String(dv.missed_calls_weekly || "").replace(/[^0-9.]/g, ""));
const r = Number(String(dv.close_rate_pct || "").replace(/[^0-9.]/g, ""));
const a = Number(String(dv.avg_job_value || "").replace(/[$,]/g, ""));
const missing = [];
if (!Number.isFinite(w) || w <= 0) missing.push("missed_calls_weekly");
if (!Number.isFinite(r) || r <= 0) missing.push("close_rate_pct");
if (!Number.isFinite(a) || a <= 0) missing.push("avg_job_value");
if (missing.length) return { ok: false, error: "missing_leak_inputs", missing };
const weekly = w * (r / 100) * a;
const monthly = Math.floor(weekly * 4.33 / 100) * 100;
return { ok: true, weekly_leak: Math.floor(weekly).toLocaleString("en-US"), monthly_leak: monthly.toLocaleString("en-US") };
